import Image from "next/image";
import { FlipSentences } from "@/components/flip-sentences";
import { PronounceName } from "@/components/pronounce-name";
import { site } from "@/lib/site";

/** "Dhruv Sharma" → "DS". */
function initials(name: string): string {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

/**
 * The portrait slot is a monogram plate, not a gap waiting to be filled: with
 * no photograph set it draws the initials in the display face, so the slot
 * reads as a mark of its own rather than as a missing image.
 *
 * 128px on a phone, 160px on desktop — the portrait is one of the two things
 * the hero is for, so it is sized to hold the row rather than to sit politely
 * beside the name.
 */
function Avatar() {
  return (
    <div className="relative m-0.5 size-32 overflow-hidden rounded-xl border border-line bg-muted ring-1 ring-border/50 select-none sm:size-40">
      {site.avatar ? (
        <Image
          src={site.avatar}
          alt={site.name}
          fill
          sizes="(min-width: 640px) 160px, 128px"
          priority
          className="object-cover"
        />
      ) : (
        <span
          role="img"
          aria-label={`${site.name}, monogram`}
          className="absolute inset-0 grid place-items-center"
        >
          {/* A mount inset from the plate edge, like the figures elsewhere
              carry — the monogram is a mark this site drew, not a photograph
              that failed to load, and it should look like it was meant. */}
          <span
            aria-hidden
            className="absolute inset-2 rounded-md border border-line"
          />
          <span
            aria-hidden
            className="relative font-heading text-5xl font-medium tracking-tight text-foreground sm:text-6xl"
          >
            {initials(site.name)}
          </span>
        </span>
      )}
    </div>
  );
}

/**
 * The hero is a four-cell frame rather than a stacked block: the monogram sits
 * in its own gutter column, and the name and role stack against the bottom
 * edge so both meet one baseline. Nothing here is centred.
 *
 * The upper plate is deliberately blank — cleared down to the sheet, waiting
 * on what goes there next.
 */
export function ProfileHeader() {
  return (
    <div className="screen-line-bottom relative grid grid-cols-[auto_1fr] grid-rows-[1fr_auto] overflow-y-clip border-x border-line">
      {/* Empty on purpose. The cell keeps the hero's proportions so the frame
          below it does not ride up to the header; it holds nothing else. */}
      <div
        aria-hidden
        className="col-span-2 aspect-[556/354] w-full bg-red-500 sm:col-span-1 sm:col-start-2"
      />

      <div className="flex flex-col sm:row-span-2 sm:row-start-1">
        <div aria-hidden className="flex-1 bg-red-500" />
        <div className="screen-line-top shrink-0 border-r border-line">
          <Avatar />
        </div>
      </div>

      <div className="flex flex-col">
        <div className="z-1 mt-auto border-t border-line">
          <h1 className="-translate-y-px flex items-center gap-2 pl-4 text-[2rem]/none font-medium tracking-tight">
            {site.name}
            {/* Inside the heading, not beside it: the button is about this
                name, and a name and the way to hear it are one object. */}
            <PronounceName />
          </h1>
          {/* The one line that reads as a caption rather than as prose, so it
              is set in mono at the small size — and swept once on arrival,
              which is the reference's own way of pointing at it without
              shouting. */}
          <FlipSentences
            sentences={site.flipSentences}
            className="h-12.5 border-t border-line py-1 pl-4 font-mono text-sm text-balance text-muted-foreground sm:h-9"
          />
        </div>
      </div>
    </div>
  );
}
=== token-ridge.tsx ===
import type { DailyTokens } from "@/lib/ai-activity";
import { buildTokenRidge, RIDGE_VIEWBOX } from "@/lib/token-ridge";
import { cn } from "@/lib/utils";

/**
 * The record drawn as a range, for the hero's figure plate.
 *
 * The plate is a window on a shape, not a chart: there is no axis, no rule and
 * no tick, because a silhouette that has to be measured off the page is a chart
 * pretending to be a picture. The exact quantities are one panel down, in Fig.
 * 2, which is what licenses the drawing to carry none.
 *
 * One silhouette, one crest, one ground line. The fill is a flat tint mixed off
 * the ink and the page rather than a fade, because a gradient here would be the
 * only one on the site; the crest is a hairline at the same weight as every
 * rule around it, so the drawing is made of the page's own marks.
 *
 * `preserveAspectRatio="none"` because the figure is normalised: the ridge
 * fills the plate at every width instead of letterboxing inside it. The only
 * thing that must survive that stretch is the line, and it carries
 * `vector-effect` so it is one hairline at every rail width.
 *
 * No component renders this alone — it is the drawing inside a `<figure>` that
 * the hero owns, exactly as the isometric plate was before it.
 */
export function TokenRidge({
  days,
  className,
  ...props
}: { days: readonly DailyTokens[] } & React.ComponentProps<"svg">) {
  const ridge = buildTokenRidge(days);
  if (!ridge.line) return null;

  return (
    <svg
      viewBox={`0 0 ${RIDGE_VIEWBOX.width} ${RIDGE_VIEWBOX.height}`}
      preserveAspectRatio="none"
      aria-hidden="true"
      className={cn("text-foreground select-none", className)}
      {...props}
    >
      {/* Mixed off the ink and the page so the tint follows the theme rather
          than naming a colour of its own. */}
      <path
        d={ridge.area}
        fill="color-mix(in oklab, var(--foreground) 9%, var(--background))"
      />
      <path
        d={ridge.line}
        fill="none"
        stroke="currentColor"
        strokeOpacity={0.45}
        strokeWidth={1}
        strokeLinejoin="round"
        strokeLinecap="round"
        vectorEffect="non-scaling-stroke"
      />
      {/* The mass has to stand on something. Without this the fill just stops
          where the plate's padding starts, and a silhouette that stops rather
          than rests reads as a crop. */}
      <line
        x1={0}
        y1={RIDGE_VIEWBOX.height}
        x2={RIDGE_VIEWBOX.width}
        y2={RIDGE_VIEWBOX.height}
        stroke="currentColor"
        strokeOpacity={0.45}
        strokeWidth={1}
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
}

/** What the silhouette says out loud, for a reader who cannot see it. */
export function tokenRidgeDescription(days: readonly DailyTokens[]): string {
  const ridge = buildTokenRidge(days);
  if (!ridge.line) return "";
  return `Daily token use across the ${ridge.span.days} days from ${ridge.span.from} to ${ridge.span.to}, drawn as a smoothed range. Exact daily figures are in the token activity grid below.`;
}
=== lib/tokscale.ts ===
import {
  AI_ACTIVITY_MAX_DAYS,
  AI_ACTIVITY_TIMEZONE,
  type AiActivityPayload,
  parseAiActivityPayload,
} from "@/lib/ai-activity-payload";

/**
 * Public read API published by the `tokscale-sync` CLI. Reads are
 * unauthenticated; only daily combined totals are consumed here.
 */
const DEFAULT_TOKSCALE_API =
  "https://tokscale-sync-api.dhruv-sharma10102005.workers.dev";

type TokscaleDay = { date: string; tokens: number };

function tokscaleEndpoint(): string {
  const base = process.env.TOKSCALE_API_URL?.trim() || DEFAULT_TOKSCALE_API;
  return `${base.replace(/\/+$/, "")}/v1/daily`;
}

/**
 * Narrow the Worker response to the day rows this site publishes. Rows are
 * sparse (absent days are measured zeros) and the newest row is today, so the
 * tail is kept and older history is dropped once the cap is hit.
 */
export function daysFromTokscaleResponse(value: unknown): TokscaleDay[] | null {
  if (!value || typeof value !== "object") return null;
  const raw = (value as { days?: unknown }).days;
  if (!Array.isArray(raw)) return null;

  const days: TokscaleDay[] = [];
  for (const entry of raw) {
    if (!entry || typeof entry !== "object") return null;
    const date = (entry as { date?: unknown }).date;
    const tokens = (entry as { tokens?: unknown }).tokens;
    if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return null;
    }
    if (typeof tokens !== "number" || !Number.isFinite(tokens) || tokens < 0) {
      return null;
    }
    days.push({ date, tokens });
  }
  if (days.length === 0) return null;

  days.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  return days.slice(-AI_ACTIVITY_MAX_DAYS);
}

export function payloadFromTokscaleResponse(
  value: unknown,
  generatedAt: string,
): AiActivityPayload | null {
  const days = daysFromTokscaleResponse(value);
  if (!days) return null;

  return parseAiActivityPayload({
    version: 1,
    generatedAt,
    timezone: AI_ACTIVITY_TIMEZONE,
    days,
    lifetimeTokens: days.reduce((sum, day) => sum + day.tokens, 0),
  });
}

export async function fetchTokscaleAiActivityPayload(): Promise<AiActivityPayload | null> {
  const url = tokscaleEndpoint();
  try {
    const res = await fetch(url, { next: { revalidate: 3600 } });
    if (!res.ok) {
      console.warn(`[ai-activity] tokscale fetch HTTP ${res.status} for ${url}`);
      return null;
    }
    const payload = payloadFromTokscaleResponse(
      await res.json(),
      new Date().toISOString(),
    );
    if (!payload) {
      console.warn("[ai-activity] tokscale payload failed validation");
      return null;
    }
    return payload;
  } catch (error) {
    console.warn("[ai-activity] tokscale fetch failed", error);
    return null;
  }
}

