import {
  AI_ACTIVITY_TIMEZONE,
  calendarDateInTimeZone,
  type AiActivityPayload,
  shiftYmd,
  weekdayIndex,
} from "@/lib/ai-activity-payload";

export type DailyTokens = {
  date: string;
  tokens: number;
};

export type Intensity = 0 | 1 | 2 | 3 | 4;

export type ActivityDay = DailyTokens & {
  intensity: Intensity;
};

/**
 * The four numbers under the title. One total is a milestone and says nothing
 * about whether the habit is still alive; four nested windows say the same
 * thing the grid says, in figures, for the Visitor who reads numbers before
 * pictures. All but the first are sums of the drawn series, so they can never
 * disagree with the cells above them.
 */
export type ActivityTotals = {
  /** All-time, from the payload — not the sum of the drawn window. */
  lifetime: number;
  days30: number;
  days7: number;
  today: number;
};

export type AiActivity = {
  days: ActivityDay[];
  /** All-time total, from the payload — not the sum of the drawn window. */
  lifetimeTokens: number;
  totals: ActivityTotals;
  timezone: string;
};

export type AiActivitySource = "blob" | "fallback";

/**
 * Four filled steps, cut at the quartiles of the days that had any work in
 * them — not at quarters of the busiest day.
 *
 * A single 400M-token afternoon against 140 ordinary days is what a scale
 * measured off the maximum draws: one black square and a grey field. Cutting
 * at the quartiles spends the four steps on the days there actually are, so
 * the grid reads as a distribution rather than as one outlier and its
 * shadow.
 */
export type IntensityThresholds = readonly [number, number, number];

export function quartileThresholds(
  days: readonly DailyTokens[],
): IntensityThresholds {
  const positive = days
    .map((day) => day.tokens)
    .filter((tokens) => tokens > 0)
    .sort((a, b) => a - b);
  if (positive.length === 0) return [0, 0, 0];
  const at = (ratio: number) =>
    positive[
      Math.min(positive.length - 1, Math.floor(positive.length * ratio))
    ]!;
  return [at(0.25), at(0.5), at(0.75)];
}

export function intensityFromTokens(
  tokens: number,
  thresholds: IntensityThresholds,
): Intensity {
  if (tokens <= 0) return 0;
  if (tokens <= thresholds[0]) return 1;
  if (tokens <= thresholds[1]) return 2;
  if (tokens <= thresholds[2]) return 3;
  return 4;
}

/**
 * The frame is a fixed year, and it does not move.
 *
 * An earlier version chose the window from the record — walk back for as long
 * as each month was worked in, stop at the first that was not — which meant the
 * figure was a different shape every month and a different shape again on the
 * day a quiet month rolled out of it. A measure whose axis changes with what it
 * measures is not a measure. So the grid is a calendar: fifty-two weeks back
 * from today, Sunday-aligned, exactly as the reference and every graph like it
 * draws one. The months before the habit existed are drawn empty, which is what
 * they were, and the record reads as having started rather than as having been
 * cropped.
 */
export const ACTIVITY_WEEKS = 52;

/**
 * The Sunday that opens the window: this week's Sunday, then fifty-two Sundays
 * back from it.
 *
 * Counting whole weeks off the current week — rather than counting 364 days
 * back from today and rounding — is what makes the plate exactly 53 columns on
 * every day of every week. Counting days puts a Saturday at exactly 52 columns
 * and every other day at 53, and a figure that loses a column once a week is a
 * figure that moves under the Visitor.
 */
export function activityWindowStart(
  today: string,
  weeks = ACTIVITY_WEEKS,
): string {
  return shiftYmd(today, -(weekdayIndex(today) + weeks * 7));
}

/**
 * Expand a sparse series into consecutive calendar days from `start` to `end`.
 *
 * Inside this window an absent day is a measured zero, not a hole: the meter
 * reads every local session on the machine, so a day it never mentions is a
 * day nothing ran. The one genuinely unknown day is today, which the nightly
 * sync has not reached yet — and today's zero is drawn as the emptiest step,
 * which is what it is.
 */
export function buildDailySeries(
  days: readonly DailyTokens[],
  start: string,
  end: string,
): DailyTokens[] {
  const byDate = new Map(days.map((day) => [day.date, day.tokens]));
  const series: DailyTokens[] = [];
  for (let cursor = start; cursor <= end; cursor = shiftYmd(cursor, 1)) {
    series.push({ date: cursor, tokens: byDate.get(cursor) ?? 0 });
  }
  return series;
}

/** Sum of the last `count` days of a consecutive series ending today. */
function sumTrailing(days: readonly DailyTokens[], count: number): number {
  return days
    .slice(-count)
    .reduce((total, day) => total + Math.max(0, day.tokens), 0);
}

export function buildAiActivity(
  series: readonly DailyTokens[],
  options?: { timezone?: string; lifetimeTokens?: number },
): AiActivity {
  const thresholds = quartileThresholds(series);
  const lifetimeTokens =
    options?.lifetimeTokens ??
    series.reduce((sum, day) => sum + day.tokens, 0);

  return {
    days: series.map((day) => ({
      ...day,
      intensity: intensityFromTokens(day.tokens, thresholds),
    })),
    lifetimeTokens,
    totals: {
      lifetime: lifetimeTokens,
      days30: sumTrailing(series, 30),
      days7: sumTrailing(series, 7),
      today: sumTrailing(series, 1),
    },
    timezone: options?.timezone ?? AI_ACTIVITY_TIMEZONE,
  };
}

export function materializeAiActivity(
  payload: AiActivityPayload,
  now = new Date(),
): AiActivity {
  const timezone = payload.timezone || AI_ACTIVITY_TIMEZONE;
  const today = calendarDateInTimeZone(now, timezone);
  const start = activityWindowStart(today);

  return buildAiActivity(buildDailySeries(payload.days, start, today), {
    timezone,
    lifetimeTokens: payload.lifetimeTokens,
  });
}

/** Exact count. Used where a number is a number: alt text, tests, scripts. */
export function formatTokenCount(tokens: number): string {
  return new Intl.NumberFormat("en-US").format(tokens);
}

/**
 * The number as it is read aloud: `10.4B`, `512M`, `84.2K`. Ten billion is
 * eleven digits, and eleven digits is a serial number, not a quantity — the
 * page wants the magnitude, and the magnitude is the first three characters.
 */
export function formatCompactTokens(tokens: number): string {
  const value = Math.max(0, Math.round(tokens));
  for (const [limit, suffix] of [
    [1e12, "T"],
    [1e9, "B"],
    [1e6, "M"],
    [1e3, "K"],
  ] as const) {
    if (value >= limit) {
      const scaled = value / limit;
      return `${scaled >= 100 ? Math.round(scaled) : Number(scaled.toFixed(1))}${suffix}`;
    }
  }
  return String(value);
}

/**
 * Published AI Activity payload (nightly → Vercel Blob).
 * Public-safe: daily combined token totals only.
 */
export type AiActivityPayload = {
  version: 1;
  generatedAt: string;
  timezone: string;
  /** Complete days only (through yesterday in `timezone`). */
  days: { date: string; tokens: number }[];
  lifetimeTokens: number;
};

export const AI_ACTIVITY_TIMEZONE = "Asia/Kolkata";
export const AI_ACTIVITY_BLOB_PATH = "ai-activity/latest.json";
export const AI_ACTIVITY_MAX_DAYS = 800;
const MAX_GENERATED_AT_LEN = 40;
const MAX_TIMEZONE_LEN = 64;

export function isValidIanaTimeZone(timeZone: string): boolean {
  if (
    timeZone.length < 1 ||
    timeZone.length > MAX_TIMEZONE_LEN ||
    timeZone !== timeZone.trim()
  ) {
    return false;
  }
  try {
    Intl.DateTimeFormat("en-US", { timeZone });
    return true;
  } catch {
    return false;
  }
}

export function isAiActivityPayload(value: unknown): value is AiActivityPayload {
  if (!value || typeof value !== "object") return false;
  const v = value as Record<string, unknown>;
  if (v.version !== 1) return false;
  if (
    typeof v.generatedAt !== "string" ||
    v.generatedAt.length === 0 ||
    v.generatedAt.length > MAX_GENERATED_AT_LEN
  ) {
    return false;
  }
  if (typeof v.timezone !== "string" || !isValidIanaTimeZone(v.timezone)) {
    return false;
  }
  if (
    typeof v.lifetimeTokens !== "number" ||
    !Number.isFinite(v.lifetimeTokens) ||
    v.lifetimeTokens < 0
  ) {
    return false;
  }
  if (!Array.isArray(v.days)) return false;
  if (v.days.length === 0 || v.days.length > AI_ACTIVITY_MAX_DAYS) return false;

  const seen = new Set<string>();
  for (const day of v.days) {
    if (!day || typeof day !== "object") return false;
    const date = (day as { date?: unknown }).date;
    const tokens = (day as { tokens?: unknown }).tokens;
    if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return false;
    }
    if (seen.has(date)) return false;
    seen.add(date);
    if (
      typeof tokens !== "number" ||
      !Number.isFinite(tokens) ||
      tokens < 0
    ) {
      return false;
    }
  }
  return true;
}

export function parseAiActivityPayload(
  value: unknown,
): AiActivityPayload | null {
  return isAiActivityPayload(value) ? value : null;
}

/** Reject payloads whose days extend past yesterday in the payload timezone. */
export function payloadDaysWithinHistory(
  payload: AiActivityPayload,
  now = new Date(),
): boolean {
  const cutoff = yesterdayInTimeZone(now, payload.timezone);
  return payload.days.every((d) => d.date <= cutoff);
}

/** Calendar YYYY-MM-DD in a timezone. */
export function calendarDateInTimeZone(date: Date, timeZone: string): string {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(date);
}

/** Shift a YYYY-MM-DD by whole calendar days (noon-UTC probe). */
export function shiftYmd(date: string, deltaDays: number): string {
  const [y, m, d] = date.split("-").map(Number);
  const utcNoon = new Date(Date.UTC(y!, m! - 1, d!, 12, 0, 0));
  utcNoon.setUTCDate(utcNoon.getUTCDate() + deltaDays);
  return calendarDateInTimeZone(utcNoon, "UTC");
}

/** First day of the month a date falls in. */
/** Day of week (0 = Sunday) for a YYYY-MM-DD calendar date. */
export function weekdayIndex(date: string): number {
  const [y, m, d] = date.split("-").map(Number);
  return new Date(Date.UTC(y!, m! - 1, d!, 12)).getUTCDay();
}

export function startOfMonth(date: string): string {
  return `${date.slice(0, 7)}-01`;
}

/** Same day-of-month `deltaMonths` away, clamped to the 1st. */
export function shiftMonth(date: string, deltaMonths: number): string {
  const [y, m] = date.split("-").map(Number);
  const total = y! * 12 + (m! - 1) + deltaMonths;
  const year = Math.floor(total / 12);
  const month = total - year * 12 + 1;
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-01`;
}

/** Previous calendar day (YYYY-MM-DD) in a timezone. */
export function yesterdayInTimeZone(now: Date, timeZone: string): string {
  return shiftYmd(calendarDateInTimeZone(now, timeZone), -1);
}

import { cn } from "@/lib/utils";

/**
 * Fig. 1 — the hero construction.
 *
 * Drawn, not rendered: faces are outlined and hatched rather than filled with
 * tone, and the floor lattice runs off every edge of the plate to be cut there.
 * That is the frame's own habit — a line is stopped by the viewport, never
 * tidied to fit — and it is what keeps the figure attached to the page instead
 * of floating on it.
 *
 * Geometry is true isometric: one edge length, the 30° axes, everything else
 * derived. This is a figure, not the brand mark — the mark is `ShortMark`.
 */

const EDGE = 20;
const HALF_W = (EDGE * Math.sqrt(3)) / 2; // horizontal run of one axis
const HALF_H = EDGE / 2; // vertical rise of one axis

function points(pairs: Array<[number, number]>): string {
  return pairs.map(([x, y]) => `${round(x)},${round(y)}`).join(" ");
}

function round(n: number): number {
  return Math.round(n * 1000) / 1000;
}

/** Corner (i, j) of the cell lattice, raised by `lift` edge-lengths. */
function corner(i: number, j: number, lift: number): [number, number] {
  return [(i - j) * HALF_W, (i + j) * HALF_H - lift * EDGE];
}

/** Footprint is inclusive on both axes; `thick` and `lift` are in edge-lengths. */
type Slab = {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  lift: number;
  thick: number;
};

/**
 * Three platforms stepping down toward the viewer. Authored back-to-front:
 * side faces are painted with the page background, so each slab occludes the
 * one behind it without any depth sorting.
 */
const SLABS: readonly Slab[] = [
  { x0: 0, y0: 0, x1: 3, y1: 1, lift: 1.2, thick: 0.4 },
  { x0: 2, y0: 2, x1: 7, y1: 3, lift: 0.6, thick: 0.4 },
  { x0: 5, y0: 4, x1: 11, y1: 5, lift: 0, thick: 0.4 },
];

function SlabShape({ slab }: { slab: Slab }) {
  const { x0, y0, x1, y1, lift, thick } = slab;
  const back = corner(x0, y0, lift);
  const right = corner(x1 + 1, y0, lift);
  const front = corner(x1 + 1, y1 + 1, lift);
  const left = corner(x0, y1 + 1, lift);
  const drop = thick * EDGE;
  const down = ([x, y]: [number, number]): [number, number] => [x, y + drop];

  return (
    <g stroke="currentColor" strokeWidth={0.6} strokeLinejoin="round">
      <polygon
        points={points([left, front, down(front), down(left)])}
        fill="var(--background)"
        strokeOpacity={0.55}
      />
      <polygon
        points={points([front, right, down(right), down(front)])}
        fill="var(--background)"
        strokeOpacity={0.35}
      />
      <polygon
        points={points([back, right, front, left])}
        fill="url(#site-figure-hatch)"
        strokeOpacity={0.7}
      />
    </g>
  );
}

/** Generous enough that every line leaves the viewBox rather than ending in it. */
const FLOOR = { lo: -8, hi: 20, centre: 6 };

function FloorLattice() {
  const lines: Array<[[number, number], [number, number], number]> = [];
  for (let n = FLOOR.lo; n <= FLOOR.hi; n += 1) {
    // Fade with distance from the figure so the cut ends are already faint.
    const fade = Math.max(
      0,
      1 - Math.abs(n - FLOOR.centre) / (FLOOR.hi - FLOOR.lo) / 0.55,
    );
    if (fade === 0) continue;
    lines.push([
      corner(FLOOR.lo, n, -0.4),
      corner(FLOOR.hi, n, -0.4),
      fade,
    ]);
    lines.push([
      corner(n, FLOOR.lo, -0.4),
      corner(n, FLOOR.hi, -0.4),
      fade,
    ]);
  }

  return (
    <g stroke="currentColor" strokeWidth={0.5}>
      {lines.map(([[x1, y1], [x2, y2], fade], i) => (
        <line
          key={i}
          x1={round(x1)}
          y1={round(y1)}
          x2={round(x2)}
          y2={round(y2)}
          strokeOpacity={round(0.16 * fade)}
        />
      ))}
    </g>
  );
}

export function SiteFigure({
  className,
  ...props
}: React.ComponentProps<"svg">) {
  return (
    <svg
      viewBox="-193 -34 490 232"
      // Cover, don't letterbox. The plate is a window onto a larger drawing,
      // so the lattice runs to all four edges and is cut there.
      preserveAspectRatio="xMidYMid slice"
      className={cn("text-foreground", className)}
      aria-hidden="true"
      {...props}
    >
      <defs>
        {/* Hatching on the 30° axis, so the shading is made of the same lines
            as everything else on the page. */}
        <pattern
          id="site-figure-hatch"
          width="5"
          height="5"
          patternUnits="userSpaceOnUse"
          patternTransform="rotate(-30)"
        >
          <line
            x1="0"
            y1="0"
            x2="0"
            y2="5"
            stroke="currentColor"
            strokeWidth="0.6"
            strokeOpacity="0.3"
          />
        </pattern>
      </defs>

      <FloorLattice />
      {SLABS.map((slab) => (
        <SlabShape key={`${slab.x0}-${slab.y0}-${slab.lift}`} slab={slab} />
      ))}
    </svg>
  );
}

import Image from "next/image";
import { FlipSentences } from "@/components/flip-sentences";
import { PronounceName } from "@/components/pronounce-name";
import { SiteFigure } from "@/components/site-figure";
import { site } from "@/lib/site";

/** "Dhruv Sharma" → "DS". */
function initials(name: string): string {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

/**
 * The portrait slot is a monogram plate, not a gap waiting to be filled: with
 * no photograph set it draws the initials in the display face, so the slot
 * reads as a mark of its own rather than as a missing image.
 *
 * 128px on a phone, 160px on desktop — the portrait is one of the two things
 * the hero is for, so it is sized to hold the row rather than to sit politely
 * beside the name.
 */
function Avatar() {
  return (
    <div className="relative m-0.5 size-32 overflow-hidden rounded-full border border-line bg-muted ring-1 ring-border/50 select-none sm:size-40">
      {site.avatar ? (
        <Image
          src={site.avatar}
          alt={`${site.name}, profile portrait`}
          fill
          sizes="(min-width: 640px) 160px, 128px"
          priority
          className="object-contain"
        />
      ) : (
        <span
          role="img"
          aria-label={`${site.name}, monogram`}
          className="absolute inset-0 grid place-items-center"
        >
          {/* A mount inset from the plate edge, like the figures elsewhere
              carry — the monogram is a mark this site drew, not a photograph
              that failed to load, and it should look like it was meant. No
              texture behind it: the hero is a plain sheet, and the only
              drawing on it is the one inside Fig. 1's own frame. */}
          <span
            aria-hidden
            className="absolute inset-2 rounded-md border border-line"
          />
          <span
            aria-hidden
            className="relative font-heading text-5xl font-medium tracking-tight text-foreground sm:text-6xl"
          >
            {initials(site.name)}
          </span>
        </span>
      )}
    </div>
  );
}

/**
 * The hero is a four-cell frame rather than a stacked block: the mark occupies
 * a plate captioned like a figure, the avatar sits in its own gutter column,
 * and the name and role stack against the bottom edge so all three meet on one
 * baseline. Nothing here is centred.
 */
export function ProfileHeader() {
  return (
    <div className="screen-line-bottom relative grid grid-cols-[auto_1fr] grid-rows-[1fr_auto] overflow-y-clip border-x border-line">
      {/* Nothing bleeds out of here. The reference lets its hero texture run
          past the rail and off the screen; ours does not. A pattern outside
          the frame turns the top of the page into wallpaper, and the only
          lines the hero needs are the ones that divide it. */}
      <figure className="relative col-span-2 p-2 sm:col-span-1 sm:col-start-2 sm:p-4">
        {/* Fills the plate rather than sitting inside it: the drawing is
            scaled to cover and cut at the edges, which is what makes the
            lattice read as continuing past the frame.

            The plate keeps a ratio rather than a height, so it grows with the
            rail instead of stepping at the breakpoint — the reference's plate
            is the same shape at every width it is drawn at. */}
        <SiteFigure className="aspect-[556/354] w-full" />
        <figcaption className="pointer-events-none absolute right-2 bottom-2 text-sm leading-none tracking-wide text-[color-mix(in_oklab,var(--muted-foreground)_60%,var(--background))] tabular-nums select-none sm:right-4 sm:bottom-4">
          Fig. 1.
        </figcaption>
      </figure>

      <div className="flex flex-col sm:row-span-2 sm:row-start-1">
        <div className="screen-line-top mt-auto shrink-0 border-r border-line">
          <Avatar />
        </div>
      </div>

      <div className="flex flex-col">
        <div className="z-1 mt-auto border-t border-line">
          <h1 className="-translate-y-px flex items-center gap-2 pl-4 text-[2rem]/none font-medium tracking-tight">
            {site.name}
            {/* Inside the heading, not beside it: the button is about this
                name, and a name and the way to hear it are one object. */}
            <PronounceName />
          </h1>
          {/* The one line that reads as a caption rather than as prose, so it
              is set in mono at the small size — and swept once on arrival,
              which is the reference's own way of pointing at it without
              shouting. */}
          <FlipSentences
            sentences={site.flipSentences}
            className="h-12.5 border-t border-line py-1 pl-4 font-mono text-sm text-balance text-muted-foreground sm:h-9"
          />
        </div>
      </div>
    </div>
  );
}

